import Foundation
@testable import SafarierCore

public enum AutomationSessionCases {
    struct Failure: Error { let label: String }
    public static func run() throws -> Int {
        var checks = 0
        func check(_ ok: @autoclosure () -> Bool, _ label: String) throws { checks += 1; if !ok() { throw Failure(label: label) } }
        let profile = UUID(), target = AutomationTargetIdentity(profileID: profile, runnerInstanceID: UUID(), windowID: UUID(), pageID: UUID())
        let token = String(repeating: "A", count: 43)
        func request(_ action: AutomationAction, _ id: UUID = UUID(), _ credential: String? = nil) -> AutomationRequest { AutomationRequest(version: 1, requestID: id, sessionID: credential ?? token, action: action) }
        let viewport = AutomationViewport(viewportWidthPoints: 100, viewportHeightPoints: 80, pixelWidth: 200, pixelHeight: 160, scaleX: 2, scaleY: 2, pageZoom: 1, viewVersion: 1)
        try check((try? AutomationSessionMachine.open(profileID: profile, allowsBackgroundAutomation: false, humanProfileRunning: false, token: token, at: 0).get()) == nil, "opt-in denied")
        try check((try? AutomationSessionMachine.open(profileID: profile, allowsBackgroundAutomation: true, humanProfileRunning: true, token: token, at: 0).get()) == nil, "human profile denied")
        let machine = try AutomationSessionMachine.open(profileID: profile, allowsBackgroundAutomation: true, humanProfileRunning: false, token: token, at: 0).get()
        try check(machine.state == .opening, "opening")
        try check(machine.bind(target: target, viewport: viewport, at: 0).isEmpty && machine.state == .ready, "bind")
        let click = request(.click(point: ViewportPoint(x: 1, y: 2), viewVersion: 1, count: 1))
        let wrong = request(.closeSession, UUID(), String(repeating: "B", count: 42) + "A")
        try check(machine.begin(wrong, permission: true, target: target, at: 1).containsReply(.sessionNotFound) && machine.state == .ready, "wrong token cannot close")
        let first = machine.begin(click, permission: true, target: target, at: 2)
        guard let ticket = first.ticket else { throw Failure(label: "click dispatch") }
        try check(machine.begin(click, permission: true, target: target, at: 3).containsReply(.sessionBusy), "inflight duplicate")
        let receipt = AutomationReply(requestID: click.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 0, viewVersion: 1)))
        try check(machine.complete(ticket: ticket, reply: receipt, at: 4).containsReply(receipt), "click complete")
        try check(machine.begin(click, permission: true, target: target, at: 5).containsReply(receipt), "click replay")
        let reuse = request(.insertText("other"), click.requestID)
        try check(machine.begin(reuse, permission: true, target: target, at: 6).containsReply(.requestIDReused), "request id reuse")
        let nav = request(.navigate(url: URL(string: "https://example.com/")!))
        let pending = machine.begin(nav, permission: true, target: target, at: 7)
        guard let oldTicket = pending.ticket else { throw Failure(label: "nav dispatch") }
        let cancellation = machine.begin(request(.cancel), permission: true, target: target, at: 8)
        try check(cancellation.hasDestroy && cancellation.ticket == nil && machine.state == .stopping, "cancel interrupts without input dispatch")
        try check(machine.complete(ticket: oldTicket, reply: AutomationReply(requestID: nav.requestID, outcome: .success(.navigationFinished(viewVersion: 2))), at: 9).isEmpty, "late completion ignored")
        _ = machine.tick(at: 8 + AutomationLimits.cleanupSeconds)
        try check(machine.state == .closed, "cleanup deadline")
        func fresh() throws -> AutomationSessionMachine {
            let m = try AutomationSessionMachine.open(profileID: profile, allowsBackgroundAutomation: true, humanProfileRunning: false, token: token, at: 0).get()
            _ = m.bind(target: target, viewport: viewport, at: 0)
            return m
        }
        func dispatch(_ effects: [AutomationSessionEffect]) throws -> AutomationSessionTicket { guard let t = effects.ticket else { throw Failure(label: "expected dispatch") }; return t }
        let releasing = try fresh(), prepareRequest = request(.releaseControl), transferID = UUID()
        let prepareTicket = try dispatch(releasing.begin(prepareRequest, permission: true, target: target, at: 1))
        try check(releasing.begin(request(.releaseControl), permission: true, target: target, at: 1.1).containsReply(.sessionBusy), "release rejects in-flight")
        let prepared = ControlReleasePreparation(target: target, transferID: transferID, inputReleased: true, artifactsCleaned: true, browserRetained: true)
        let preparedReply = AutomationReply(requestID: prepareRequest.requestID, outcome: .success(.controlReleasePrepared(prepared)))
        try check(releasing.complete(ticket: prepareTicket, reply: preparedReply, at: 1.5).containsReply(preparedReply), "release prepared")
        try check(releasing.begin(request(.commitControlRelease(transferID: UUID())), permission: true, target: target, at: 1.6).containsReply(.sessionBusy), "wrong transfer rejected")
        let commit = request(.commitControlRelease(transferID: transferID))
        let commitTicket = try dispatch(releasing.begin(commit, permission: true, target: target, at: 3.5))
        let releaseReceipt = ControlReleaseReceipt(target: target, transferID: transferID, inputReleased: true, artifactsCleaned: true, browserRetained: true, manualInteractionEnabled: true)
        let releasedReply = AutomationReply(requestID: commit.requestID, outcome: .success(.controlReleased(releaseReceipt)))
        try check(releasing.complete(ticket: commitTicket, reply: releasedReply, at: 4.5).containsReply(releasedReply) && releasing.controlReleaseCommitted && releasing.state == .released, "release committed within the release deadline")
        try check(!releasing.acceptsSessionID(token) && releasing.begin(request(.closeSession), permission: true, target: target, at: 4.6).containsReply(.sessionExpired), "released token revoked")
        try check(releasing.event(.channelClosed, at: 4.7).isEmpty, "released channel closure does not destroy")
        let releaseTimeout = try fresh(), slowPrepare = request(.releaseControl)
        let slowTicket = try dispatch(releaseTimeout.begin(slowPrepare, permission: true, target: target, at: 1))
        _ = releaseTimeout.complete(ticket: slowTicket, reply: AutomationReply(requestID: slowPrepare.requestID, outcome: .success(.controlReleasePrepared(prepared))), at: 3.5)
        _ = try dispatch(releaseTimeout.begin(request(.commitControlRelease(transferID: transferID)), permission: true, target: target, at: 5.5))
        try check(releaseTimeout.tick(at: 1 + AutomationLimits.actionSeconds).hasDestroy, "release phases share original action deadline")
        let releaseHeld = try fresh(), heldDown = request(.mouseDown(point: ViewportPoint(x: 1, y: 2), viewVersion: 1))
        let heldDownTicket = try dispatch(releaseHeld.begin(heldDown, permission: true, target: target, at: 1))
        _ = releaseHeld.complete(ticket: heldDownTicket, reply: AutomationReply(requestID: heldDown.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 1, viewVersion: 1))), at: 1.1)
        try check(releaseHeld.begin(request(.releaseControl), permission: true, target: target, at: 1.2).containsReply(.invalidPointerState), "release rejects held pointer")
        let falseProof = try fresh(), falseRequest = request(.releaseControl)
        let falseTicket = try dispatch(falseProof.begin(falseRequest, permission: true, target: target, at: 1))
        let falsePreparation = ControlReleasePreparation(target: target, transferID: UUID(), inputReleased: false, artifactsCleaned: true, browserRetained: true)
        try check(falseProof.complete(ticket: falseTicket, reply: AutomationReply(requestID: falseRequest.requestID, outcome: .success(.controlReleasePrepared(falsePreparation))), at: 1.1).hasDestroy && !falseProof.controlReleaseCommitted, "false preparation destroys")
        let releaseCancel = try fresh(), cancelPrepare = request(.releaseControl)
        let cancelPrepareTicket = try dispatch(releaseCancel.begin(cancelPrepare, permission: true, target: target, at: 1))
        _ = releaseCancel.complete(ticket: cancelPrepareTicket, reply: AutomationReply(requestID: cancelPrepare.requestID, outcome: .success(.controlReleasePrepared(prepared))), at: 1.2)
        let cancelledCommit = request(.commitControlRelease(transferID: transferID))
        let cancelledTicket = try dispatch(releaseCancel.begin(cancelledCommit, permission: true, target: target, at: 1.3))
        try check(releaseCancel.begin(request(.cancel), permission: true, target: target, at: 1.4).hasDestroy, "cancel wins against commit in flight")
        try check(releaseCancel.complete(ticket: cancelledTicket, reply: AutomationReply(requestID: cancelledCommit.requestID, outcome: .success(.controlReleased(releaseReceipt))), at: 1.5).isEmpty && !releaseCancel.controlReleaseCommitted, "late commit cannot revive cancelled release")
        let nativeInvalid = try fresh()
        try check(nativeInvalid.begin(request(.navigateByInput(input: .enter, viewVersion: 2)), permission: true, target: target, at: 1).containsReply(.targetChanged), "native navigation stale version")
        try check(nativeInvalid.begin(request(.navigateByInput(input: .click(point: ViewportPoint(x: 100, y: 1)), viewVersion: 1)), permission: true, target: target, at: 2).containsReply(.outOfBounds), "native navigation outside")
        let nativeNav = try fresh(); let nativeRequest = request(.navigateByInput(input: .enter, viewVersion: 1))
        let nativeTicket = try dispatch(nativeNav.begin(nativeRequest, permission: true, target: target, at: 1))
        try check(nativeNav.tick(at: 6).isEmpty, "native navigation retains 30 second budget")
        try check(nativeNav.begin(request(.navigateByInput(input: .click(point: ViewportPoint(x: 1, y: 2)), viewVersion: 1), nativeRequest.requestID), permission: true, target: target, at: 7).containsReply(.requestIDReused), "native navigation replay conflict")
        let nativeReply = AutomationReply(requestID: nativeRequest.requestID, outcome: .success(.navigationFinished(viewVersion: 2)))
        try check(nativeNav.complete(ticket: nativeTicket, reply: nativeReply, at: 8).containsReply(nativeReply), "native navigation new viewport")
        let nativeDeadline = try fresh(); _ = try dispatch(nativeDeadline.begin(request(.navigateByInput(input: .enter, viewVersion: 1)), permission: true, target: target, at: 1))
        try check(nativeDeadline.tick(at: 1 + AutomationLimits.navigationSeconds).hasDestroy, "native navigation deadline")
        let nativeHeld = try fresh(); let nativeDown = request(.mouseDown(point: ViewportPoint(x: 1, y: 2), viewVersion: 1))
        let nativeDownTicket = try dispatch(nativeHeld.begin(nativeDown, permission: true, target: target, at: 1))
        _ = nativeHeld.complete(ticket: nativeDownTicket, reply: AutomationReply(requestID: nativeDown.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 1, viewVersion: 1))), at: 2)
        try check(nativeHeld.begin(request(.navigateByInput(input: .enter, viewVersion: 1)), permission: true, target: target, at: 3).containsReply(.invalidPointerState), "native navigation held rejected")
        let invalids = try fresh()
        let outside = request(.move(point: ViewportPoint(x: 100, y: 2), viewVersion: 1))
        try check(invalids.begin(outside, permission: true, target: target, at: 29).containsReply(.outOfBounds), "outside rejected")
        try check(invalids.tick(at: AutomationLimits.idleSeconds).hasDestroy && invalids.state == .stopping, "outside does not renew lease")
        let malformed = try fresh()
        let nanAction = request(.move(point: ViewportPoint(x: .nan, y: 0), viewVersion: 1))
        try check(malformed.begin(nanAction, permission: true, target: target, at: 29).containsReply(.invalidRequest), "malformed action")
        try check(malformed.tick(at: AutomationLimits.idleSeconds).hasDestroy, "malformed no renewal")
        let busy = try fresh()
        let reading = request(.getState)
        _ = try dispatch(busy.begin(reading, permission: true, target: target, at: 0))
        try check(busy.begin(request(.getState), permission: true, target: target, at: 4).containsReply(.sessionBusy), "busy rejected")
        try check(busy.tick(at: AutomationLimits.actionSeconds).hasDestroy, "action timeout bounded")
        let held = try fresh()
        let down = request(.mouseDown(point: ViewportPoint(x: 1, y: 2), viewVersion: 1))
        let downTicket = try dispatch(held.begin(down, permission: true, target: target, at: 1))
        let downReply = AutomationReply(requestID: down.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 1, viewVersion: 1)))
        try check(held.complete(ticket: downTicket, reply: downReply, at: 5.9).containsReply(downReply) && held.state == .held, "down completion held")
        try check(held.begin(request(.mouseDown(point: ViewportPoint(x: 1, y: 2), viewVersion: 1)), permission: true, target: target, at: 5.95).containsReply(.invalidPointerState), "duplicate down rejected")
        let heldRead = request(.getState)
        let heldReadTicket = try dispatch(held.begin(heldRead, permission: true, target: target, at: 5.96))
        let heldState = AutomationState(target: target, url: nil, loading: false, sessionState: .held, viewVersion: 1)
        let heldReadReply = AutomationReply(requestID: heldRead.requestID, outcome: .success(.stateRead(heldState)))
        try check(held.complete(ticket: heldReadTicket, reply: heldReadReply, at: 5.97).containsReply(heldReadReply), "held valid read renews lease")
        let heldExpiry = held.tick(at: 1 + AutomationLimits.heldSeconds)
        try check(heldExpiry.hasDestroy && held.state == .stopping, "absolute hold deadline from dispatch")
        try check(!String(reflecting: heldExpiry).contains(token), "effect redaction")
        let up = try fresh()
        try check(up.begin(request(.mouseUp(point: ViewportPoint(x: 1, y: 2), viewVersion: 1)), permission: true, target: target, at: 1).containsReply(.invalidPointerState), "up without down")
        let block = try fresh(); _ = block.event(.blocked, at: 1)
        try check(block.state == .blocked && block.begin(click, permission: true, target: target, at: 2).containsReply(.sessionBlocked), "blocked rejects input")
        try check(block.begin(request(.getState), permission: true, target: target, at: 3).ticket != nil, "blocked permits read")
        let geometry = try fresh()
        let changed = AutomationViewport(viewportWidthPoints: 110, viewportHeightPoints: 80, pixelWidth: 220, pixelHeight: 160, scaleX: 2, scaleY: 2, pageZoom: 1, viewVersion: 2)
        _ = geometry.event(.geometryChanged(target: target, viewport: changed), at: 1)
        try check(geometry.begin(click, permission: true, target: target, at: 2).containsReply(.targetChanged), "stale view version")
        let other = AutomationTargetIdentity(profileID: profile, runnerInstanceID: UUID(), windowID: target.windowID, pageID: target.pageID)
        let mismatch = try fresh()
        let mismatchEffects = mismatch.begin(request(.getState), permission: true, target: other, at: 1)
        try check(mismatchEffects.containsReply(.targetChanged) && mismatchEffects.destroys(target), "target mismatch closes only bound target")
        let badTokenPermission = try fresh()
        try check(badTokenPermission.begin(wrong, permission: false, target: other, at: 1).containsReply(.sessionNotFound) && badTokenPermission.state == .ready, "token before revocation or target")
        let revoked = badTokenPermission.begin(request(.getState), permission: false, target: target, at: 2)
        try check(revoked.containsReply(.profileNotAllowed) && revoked.hasDestroy, "revocation closes")
        let brokenClock = try fresh()
        try check(brokenClock.tick(at: .nan).hasDestroy && brokenClock.state == .closed, "NaN fail closed")
        let backwards = try fresh(); _ = backwards.tick(at: 1)
        try check(backwards.tick(at: 0).hasDestroy && backwards.state == .closed, "backward clock fail closed")
        let infinite = try fresh()
        try check(infinite.tick(at: .infinity).hasDestroy && infinite.state == .closed, "infinite clock fail closed")
        let stoppingClock = try fresh(); _ = stoppingClock.begin(request(.closeSession), permission: true, target: target, at: 1)
        _ = stoppingClock.tick(at: .nan)
        try check(stoppingClock.state == .closed, "invalid cleanup clock fail closed")
        let navigation = try fresh(); let navigationRequest = request(.navigate(url: URL(string: "https://example.com/")!))
        let navigationTicket = try dispatch(navigation.begin(navigationRequest, permission: true, target: target, at: 1))
        let navigationReply = AutomationReply(requestID: navigationRequest.requestID, outcome: .success(.navigationFinished(viewVersion: 2)))
        try check(navigation.complete(ticket: navigationTicket, reply: navigationReply, at: 2).containsReply(navigationReply), "navigation completion")
        try check(navigation.begin(click, permission: true, target: target, at: 3).containsReply(.targetChanged), "navigation invalidates old coordinates")
        let newMove = request(.move(point: ViewportPoint(x: 1, y: 1), viewVersion: 2))
        try check(navigation.begin(newMove, permission: true, target: target, at: 4).ticket != nil, "new navigation version valid")
        let unbound = try AutomationSessionMachine.open(profileID: profile, allowsBackgroundAutomation: true, humanProfileRunning: false, token: token, at: 0).get()
        let unowned = AutomationTargetIdentity(profileID: UUID(), runnerInstanceID: UUID(), windowID: UUID(), pageID: UUID())
        try check(unbound.bind(target: unowned, viewport: viewport, at: 1).isEmpty && unbound.state == .closed, "opening rejects wrong profile target")
        let renewal = try fresh(); let renewalRequest = request(.getState)
        let renewalTicket = try dispatch(renewal.begin(renewalRequest, permission: true, target: target, at: 29))
        let renewalState = AutomationState(target: target, url: nil, loading: false, sessionState: .ready, viewVersion: 1)
        let renewalReply = AutomationReply(requestID: renewalRequest.requestID, outcome: .success(.stateRead(renewalState)))
        _ = renewal.complete(ticket: renewalTicket, reply: renewalReply, at: 29)
        try check(renewal.tick(at: AutomationLimits.idleSeconds).isEmpty && renewal.state == .ready, "valid operation renews idle")
        try check(renewal.tick(at: 29 + AutomationLimits.idleSeconds).hasDestroy, "renewed idle expires exactly")
        let busyLease = try fresh(); let longNav = request(.navigate(url: URL(string: "https://example.com/")!))
        _ = try dispatch(busyLease.begin(longNav, permission: true, target: target, at: 0))
        try check(busyLease.begin(request(.getState), permission: true, target: target, at: 29).containsReply(.sessionBusy), "busy at lease edge")
        try check(busyLease.tick(at: AutomationLimits.idleSeconds).hasDestroy, "busy rejection does not renew lease")
        let heldGeometry = try fresh(); let geometryDown = request(.mouseDown(point: ViewportPoint(x: 2, y: 2), viewVersion: 1))
        let geometryTicket = try dispatch(heldGeometry.begin(geometryDown, permission: true, target: target, at: 0))
        let geometryReply = AutomationReply(requestID: geometryDown.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 1, viewVersion: 1)))
        _ = heldGeometry.complete(ticket: geometryTicket, reply: geometryReply, at: 1)
        try check(heldGeometry.event(.geometryChanged(target: target, viewport: changed), at: 2).hasDestroy && heldGeometry.state == .stopping, "held geometry safely closes")
        let unicode = try fresh(); let unicodeID = UUID()
        let composed = request(.insertText("\u{e9}"), unicodeID), decomposed = request(.insertText("e\u{301}"), unicodeID)
        let unicodeTicket = try dispatch(unicode.begin(composed, permission: true, target: target, at: 1))
        try check(unicode.begin(decomposed, permission: true, target: target, at: 2).containsReply(.requestIDReused), "Unicode inflight identity")
        let unicodeReply = AutomationReply(requestID: unicodeID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 0, viewVersion: 1)))
        _ = unicode.complete(ticket: unicodeTicket, reply: unicodeReply, at: 3)
        try check(unicode.begin(decomposed, permission: true, target: target, at: 4).containsReply(.requestIDReused), "Unicode completed identity")
        let explicit = try fresh(); let close = request(.closeSession)
        let explicitEffects = explicit.begin(close, permission: true, target: target, at: 1)
        guard let explicitCleanupTicket = explicitEffects.cleanupTicket else { throw Failure(label: "explicit cleanup ticket") }
        let cleanup = CleanupReceipt(cleaned: true, terminatedOwnedRunner: false)
        let closeReply = AutomationReply(requestID: close.requestID, outcome: .success(.sessionClosed(cleanup)))
        try check(explicit.event(.cleanupFinished(ticket: explicitCleanupTicket, receipt: cleanup), at: 2).containsReply(closeReply) && explicit.state == .closed, "explicit cleanup receipt")
        try check(explicit.begin(close, permission: true, target: target, at: 3).containsReply(closeReply), "repeat close stable")
        try check(explicit.begin(close, permission: false, target: target, at: 3).containsReply(closeReply), "closed receipt stable after revocation")
        let closeCollision = request(.cancel, close.requestID)
        try check(explicit.begin(closeCollision, permission: true, target: target, at: 4).containsReply(.requestIDReused), "closed cache preserves request identity")
        let timeoutClose = try fresh(); let timeoutRequest = request(.closeSession)
        _ = timeoutClose.begin(timeoutRequest, permission: true, target: target, at: 1)
        let timeoutReceipt = AutomationReply(requestID: timeoutRequest.requestID, outcome: .success(.sessionClosed(CleanupReceipt(cleaned: false, terminatedOwnedRunner: false))))
        try check(timeoutClose.tick(at: 1 + AutomationLimits.cleanupSeconds).containsReply(timeoutReceipt) && timeoutClose.state == .closed, "cleanup timeout unverified")
        let uncertain = try fresh(); let mutation = request(.insertText("secret"))
        let uncertainTicket = try dispatch(uncertain.begin(mutation, permission: true, target: target, at: 1))
        let wrongIDReply = AutomationReply(requestID: UUID(), outcome: .success(.nativeDelivered(sequence: 1, buttons: 0, viewVersion: 1)))
        let uncertainEffects = uncertain.complete(ticket: uncertainTicket, reply: wrongIDReply, at: 2)
        try check(uncertainEffects.hasDestroy && uncertainEffects.containsIndeterminatePossible, "mismatched reply unknown mutation")
        try check(uncertain.complete(ticket: uncertainTicket, reply: wrongIDReply, at: 2).isEmpty, "late uncertain completion ignored")
        for event in [AutomationSessionEvent.permissionRevoked, .channelClosed, .runnerExited, .targetChanged] {
            let m = try fresh(); let r = request(.insertText("private")); let t = try dispatch(m.begin(r, permission: true, target: target, at: 1))
            let effects = m.event(event, at: 2)
            try check(effects.hasDestroy && effects.containsIndeterminatePossible && m.state == .stopping, "event interrupts mutation")
            let late = AutomationReply(requestID: r.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 0, viewVersion: 1)))
            try check(m.complete(ticket: t, reply: late, at: 2).isEmpty && m.state == .stopping, "event discards late result")
        }
        let epochMachine = try fresh(); let epochFirst = request(.getState)
        let firstEpoch = try dispatch(epochMachine.begin(epochFirst, permission: true, target: target, at: 1))
        let stateValue = AutomationState(target: target, url: nil, loading: false, sessionState: .ready, viewVersion: 1)
        let firstReply = AutomationReply(requestID: epochFirst.requestID, outcome: .success(.stateRead(stateValue)))
        _ = epochMachine.complete(ticket: firstEpoch, reply: firstReply, at: 2)
        let epochSecond = request(.getState), secondEpoch = try dispatch(epochMachine.begin(epochSecond, permission: true, target: target, at: 3))
        try check(firstEpoch.epoch != secondEpoch.epoch, "epoch changes between dispatches")
        try check(epochMachine.complete(ticket: firstEpoch, reply: firstReply, at: 4).isEmpty, "old ticket cannot complete new dispatch")
        let secondReply = AutomationReply(requestID: epochSecond.requestID, outcome: .success(.stateRead(stateValue)))
        try check(epochMachine.complete(ticket: secondEpoch, reply: secondReply, at: 5).containsReply(secondReply), "current ticket completes")
        let failedDown = try fresh(); let failedDownRequest = request(.mouseDown(point: ViewportPoint(x: 1, y: 1), viewVersion: 1))
        let failedDownTicket = try dispatch(failedDown.begin(failedDownRequest, permission: true, target: target, at: 1))
        let possibleDown = AutomationReply(requestID: failedDownRequest.requestID, outcome: .failure(AutomationError(code: .timeout, sideEffects: .possible)))
        try check(failedDown.complete(ticket: failedDownTicket, reply: possibleDown, at: 2).hasDestroy && failedDown.state == .stopping, "uncertain down cannot resume ready")
        let variants = [
            AutomationViewport(viewportWidthPoints: 100, viewportHeightPoints: 80, pixelWidth: 201, pixelHeight: 160, scaleX: 2, scaleY: 2, pageZoom: 1, viewVersion: 1),
            AutomationViewport(viewportWidthPoints: 100, viewportHeightPoints: 80, pixelWidth: 200, pixelHeight: 161, scaleX: 2, scaleY: 2, pageZoom: 1, viewVersion: 1),
            AutomationViewport(viewportWidthPoints: 100, viewportHeightPoints: 80, pixelWidth: 200, pixelHeight: 160, scaleX: 3, scaleY: 2, pageZoom: 1, viewVersion: 1),
            AutomationViewport(viewportWidthPoints: 100, viewportHeightPoints: 80, pixelWidth: 200, pixelHeight: 160, scaleX: 2, scaleY: 3, pageZoom: 1, viewVersion: 1),
            AutomationViewport(viewportWidthPoints: 100, viewportHeightPoints: 80, pixelWidth: 200, pixelHeight: 160, scaleX: 2, scaleY: 2, pageZoom: 2, viewVersion: 1)
        ]
        for alteredViewport in variants {
            let m = try fresh(); let r = request(.screenshot); let ticket = try dispatch(m.begin(r, permission: true, target: target, at: 1))
            let reply = AutomationReply(requestID: r.requestID, outcome: .success(.snapshotWritten(path: "/tmp/test.png", viewport: alteredViewport)))
            let effects = m.complete(ticket: ticket, reply: reply, at: 2)
            try check(effects.hasDestroy && !effects.containsReply(reply) && m.state == .stopping, "screenshot metadata mismatch rejected")
        }
        let mismatchState = try fresh(); let stateRequest = request(.getState)
        let stateTicket = try dispatch(mismatchState.begin(stateRequest, permission: true, target: target, at: 1))
        let incompatible = AutomationState(target: target, url: nil, loading: false, sessionState: .held, viewVersion: 1)
        let stateMismatchReply = AutomationReply(requestID: stateRequest.requestID, outcome: .success(.stateRead(incompatible)))
        try check(mismatchState.complete(ticket: stateTicket, reply: stateMismatchReply, at: 2).hasDestroy, "getState rejects incorrect session state")
        let terminalReuse = try fresh(); let oldClick = request(.click(point: ViewportPoint(x: 1, y: 1), viewVersion: 1, count: 1))
        let oldClickTicket = try dispatch(terminalReuse.begin(oldClick, permission: true, target: target, at: 1))
        let oldClickReply = AutomationReply(requestID: oldClick.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 0, viewVersion: 1)))
        _ = terminalReuse.complete(ticket: oldClickTicket, reply: oldClickReply, at: 2)
        let terminalClose = request(.closeSession); let terminalEffects = terminalReuse.begin(terminalClose, permission: true, target: target, at: 3)
        guard let terminalCleanupTicket = terminalEffects.cleanupTicket else { throw Failure(label: "terminal cleanup ticket") }
        _ = terminalReuse.event(.cleanupFinished(ticket: terminalCleanupTicket, receipt: CleanupReceipt(cleaned: true, terminatedOwnedRunner: false)), at: 4)
        try check(terminalReuse.begin(request(.closeSession, oldClick.requestID), permission: true, target: target, at: 5).containsReply(.requestIDReused), "old click ID cannot close")
        let newTerminalClose = request(.closeSession)
        let stableTerminalReply = AutomationReply(requestID: newTerminalClose.requestID, outcome: .success(.sessionClosed(CleanupReceipt(cleaned: true, terminatedOwnedRunner: false))))
        try check(terminalReuse.begin(newTerminalClose, permission: true, target: target, at: 6).containsReply(stableTerminalReply), "new close ID stable receipt")
        try check(terminalReuse.begin(request(.cancel, newTerminalClose.requestID), permission: true, target: target, at: 7).containsReply(.requestIDReused), "new closed ID cannot change action")
        try check(terminalReuse.begin(request(.closeSession, oldClick.requestID), permission: true, target: target, at: 40).containsReply(.requestIDReused), "closed old action ID remains rejected after lease")
        let duplicateExpiry = try fresh(); let expiryClick = request(.click(point: ViewportPoint(x: 1, y: 1), viewVersion: 1, count: 1))
        let expiryTicket = try dispatch(duplicateExpiry.begin(expiryClick, permission: true, target: target, at: 0))
        let expiredEffects = duplicateExpiry.begin(expiryClick, permission: true, target: target, at: AutomationLimits.actionSeconds)
        try check(expiredEffects.completionCount(expiryTicket) == 1 && expiredEffects.immediateCount(expiryClick.requestID) == 1 && expiredEffects.containsIndeterminatePossible && expiredEffects.hasDestroy, "duplicate at deadline routes ticket completion and immediate reply separately")
        let changedExpiry = try fresh(); let changedOld = request(.click(point: ViewportPoint(x: 1, y: 1), viewVersion: 1, count: 1))
        let changedOldTicket = try dispatch(changedExpiry.begin(changedOld, permission: true, target: target, at: 0))
        let changedIncoming = request(.insertText("different"), changedOld.requestID)
        let changedEffects = changedExpiry.begin(changedIncoming, permission: true, target: target, at: AutomationLimits.actionSeconds)
        try check(changedEffects.completionCount(changedOldTicket) == 1 && changedEffects.immediateCount(changedOld.requestID) == 1 && changedEffects.containsReply(.requestIDReused), "expiry same ID different payload retains reuse error")
        let distinctExpiry = try fresh(); let oldRequest = request(.click(point: ViewportPoint(x: 1, y: 1), viewVersion: 1, count: 1))
        let distinctTicket = try dispatch(distinctExpiry.begin(oldRequest, permission: true, target: target, at: 0))
        let newRequest = request(.getState)
        let distinctEffects = distinctExpiry.begin(newRequest, permission: true, target: target, at: AutomationLimits.actionSeconds)
        try check(distinctEffects.completionCount(distinctTicket) == 1 && distinctEffects.immediateCount(newRequest.requestID) == 1, "expiry distinct IDs have separate replies")
        let crossA = try fresh()
        let otherTarget = AutomationTargetIdentity(profileID: profile, runnerInstanceID: UUID(), windowID: UUID(), pageID: UUID())
        let otherToken = Data(repeating: 1, count: 32).base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
        let crossB = try AutomationSessionMachine.open(profileID: profile, allowsBackgroundAutomation: true, humanProfileRunning: false, token: otherToken, at: 0).get()
        _ = crossB.bind(target: otherTarget, viewport: viewport, at: 0)
        let sharedID = UUID(); let crossRequest = request(.click(point: ViewportPoint(x: 1, y: 1), viewVersion: 1, count: 1), sharedID)
        let ticketA = try dispatch(crossA.begin(crossRequest, permission: true, target: target, at: 1))
        let crossRequestB = request(.click(point: ViewportPoint(x: 1, y: 1), viewVersion: 1, count: 1), sharedID, otherToken)
        let ticketB = try dispatch(crossB.begin(crossRequestB, permission: true, target: otherTarget, at: 1))
        let crossReply = AutomationReply(requestID: sharedID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 0, viewVersion: 1)))
        try check(ticketA != ticketB, "cross-session tickets differ")
        try check(crossB.complete(ticket: ticketA, reply: crossReply, at: 2).isEmpty && crossB.state == .ready, "other session ticket rejected")
        try check(crossB.begin(crossRequestB, permission: true, target: otherTarget, at: 2).containsReply(.sessionBusy), "other session remains pending")
        try check(crossB.complete(ticket: ticketB, reply: crossReply, at: 3).containsReply(crossReply), "own session ticket completes")
        let cleanupA = try fresh(), cleanupB = try fresh()
        let cleanupAEffects = cleanupA.begin(request(.closeSession), permission: true, target: target, at: 1)
        let cleanupBEffects = cleanupB.begin(request(.closeSession), permission: true, target: target, at: 1)
        guard let cleanupTicketA = cleanupAEffects.cleanupTicket, let cleanupTicketB = cleanupBEffects.cleanupTicket else { throw Failure(label: "cleanup tickets") }
        let crossCleanupReceipt = CleanupReceipt(cleaned: true, terminatedOwnedRunner: true)
        _ = cleanupB.event(.cleanupFinished(ticket: cleanupTicketA, receipt: crossCleanupReceipt), at: 1.5)
        try check(cleanupB.state == .stopping && cleanupTicketA != cleanupTicketB, "cleanup from other session must not finish")
        _ = cleanupB.event(.cleanupFinished(ticket: cleanupTicketB, receipt: crossCleanupReceipt), at: 1.6)
        try check(cleanupB.state == .closed, "own cleanup ticket accepted")
        let pendingClose = try fresh(); let firstClose = request(.closeSession)
        let pendingCloseEffects = pendingClose.begin(firstClose, permission: true, target: target, at: 1)
        guard let pendingCloseTicket = pendingCloseEffects.waitingTicket else { throw Failure(label: "deferred close ticket") }
        try check(pendingClose.begin(request(.cancel, firstClose.requestID), permission: true, target: target, at: 1.5).containsReply(.requestIDReused), "stopping close ID cannot change action")
        let pendingDeadline = pendingClose.begin(firstClose, permission: true, target: target, at: 1 + AutomationLimits.cleanupSeconds)
        try check(pendingDeadline.immediateCount(firstClose.requestID) == 1 && pendingDeadline.completionCount(pendingCloseTicket) == 1, "cleanup deadline routes deferred and incoming separately")
        let leaseClose = try fresh(); let pendingNav = request(.navigate(url: URL(string: "https://example.com/")!))
        let leaseTicket = try dispatch(leaseClose.begin(pendingNav, permission: true, target: target, at: 0))
        let expiryEffects = leaseClose.tick(at: AutomationLimits.idleSeconds)
        guard let expiryCleanup = expiryEffects.cleanupTicket else { throw Failure(label: "lease cleanup ticket") }
        try check(expiryEffects.completionCount(leaseTicket) == 1 && expiryEffects.hasDestroy, "exact lease expires with completion")
        let lateReceipt = CleanupReceipt(cleaned: true, terminatedOwnedRunner: true)
        _ = leaseClose.event(.cleanupFinished(ticket: expiryCleanup, receipt: lateReceipt), at: AutomationLimits.idleSeconds + AutomationLimits.cleanupSeconds)
        try check(leaseClose.state == .closed, "late cleanup leaves closed")
        let terminalRequest = request(.closeSession)
        let terminalFalse = AutomationReply(requestID: terminalRequest.requestID, outcome: .success(.sessionClosed(CleanupReceipt(cleaned: false, terminatedOwnedRunner: false))))
        try check(leaseClose.begin(terminalRequest, permission: true, target: target, at: AutomationLimits.idleSeconds + AutomationLimits.cleanupSeconds + 1).containsReply(terminalFalse), "late cleanup cannot claim success")
        try check(leaseClose.begin(request(.closeSession, pendingNav.requestID), permission: true, target: target, at: AutomationLimits.idleSeconds + AutomationLimits.cleanupSeconds + 2).containsReply(.requestIDReused), "expired active ID cannot become close")
        let replayValue = Mirror(reflecting: leaseClose).children.first { $0.label == "replay" }?.value
        let released = replayValue.map { Mirror(reflecting: $0).displayStyle == .optional && Mirror(reflecting: $0).children.isEmpty } ?? false
        try check(released, "terminal session releases active replay payloads")
        let closingAtLease = try fresh(); let boundaryClose = request(.closeSession)
        let boundaryEffects = closingAtLease.begin(boundaryClose, permission: true, target: target, at: AutomationLimits.idleSeconds - 1)
        guard let boundaryCleanup = boundaryEffects.cleanupTicket, let boundaryWait = boundaryEffects.waitingTicket else { throw Failure(label: "boundary close tickets") }
        let atBoundary = closingAtLease.event(.cleanupFinished(ticket: boundaryCleanup, receipt: lateReceipt), at: AutomationLimits.idleSeconds - 1 + AutomationLimits.cleanupSeconds)
        let boundaryReply = AutomationReply(requestID: boundaryClose.requestID, outcome: .success(.sessionClosed(CleanupReceipt(cleaned: false, terminatedOwnedRunner: false))))
        try check(atBoundary.completionCount(boundaryWait) == 1 && atBoundary.containsReply(boundaryReply), "cleanup deadline no cache revival")
        try check(closingAtLease.begin(boundaryClose, permission: true, target: target, at: AutomationLimits.idleSeconds + AutomationLimits.cleanupSeconds).containsReply(boundaryReply), "terminal close stable after expired lease")
        let capacity = try fresh()
        for _ in 0..<256 {
            let r = request(.getState), ticket = try dispatch(capacity.begin(r, permission: true, target: target, at: 1))
            let value = AutomationState(target: target, url: nil, loading: false, sessionState: .ready, viewVersion: 1)
            let rr = AutomationReply(requestID: r.requestID, outcome: .success(.stateRead(value)))
            try check(capacity.complete(ticket: ticket, reply: rr, at: 1).containsReply(rr), "capacity entry")
        }
        try check(capacity.begin(request(.getState), permission: true, target: target, at: 2).containsReply(.replayWindowFull), "replay full rejects new work")
        let fullCancel = request(.cancel)
        let fullCancelEffects = capacity.begin(fullCancel, permission: true, target: target, at: 3)
        try check(fullCancelEffects.hasDestroy, "full replay does not prevent safety cancel")
        guard let fullCleanup = fullCancelEffects.cleanupTicket else { throw Failure(label: "full replay cleanup ticket") }
        let fullReceipt = CleanupReceipt(cleaned: false, terminatedOwnedRunner: false)
        _ = capacity.event(.cleanupFinished(ticket: fullCleanup, receipt: fullReceipt), at: 4)
        let fullReply = AutomationReply(requestID: fullCancel.requestID, outcome: .success(.sessionClosed(fullReceipt)))
        try check(capacity.begin(fullCancel, permission: true, target: target, at: 5).containsReply(fullReply), "unreserved safety close stable")
        try check(capacity.begin(request(.closeSession, fullCancel.requestID), permission: true, target: target, at: 6).containsReply(.requestIDReused), "unreserved safety close ID cannot change action")
        try check(capacity.begin(request(.closeSession), permission: true, target: target, at: 7).containsReply(.replayWindowFull), "full terminal cache does not evict")
        let exactHold = try fresh(); let exactDown = request(.mouseDown(point: ViewportPoint(x: 1, y: 1), viewVersion: 1))
        let exactTicket = try dispatch(exactHold.begin(exactDown, permission: true, target: target, at: 0))
        let tooLate = AutomationReply(requestID: exactDown.requestID, outcome: .success(.nativeDelivered(sequence: 1, buttons: 1, viewVersion: 1)))
        let exactEffects = exactHold.complete(ticket: exactTicket, reply: tooLate, at: AutomationLimits.heldSeconds)
        try check(exactEffects.hasDestroy && exactEffects.completionCount(exactTicket) == 1 && !exactEffects.containsReply(tooLate), "down completion at hold boundary rejected")
        return checks
    }
}
private extension Array where Element == AutomationSessionEffect {
    var ticket: AutomationSessionTicket? { for e in self { if case .dispatch(let t, _) = e { return t } }; return nil }
    var hasDestroy: Bool { contains { if case .destroyOwnedTarget = $0 { return true }; return false } }
    func destroys(_ target: AutomationTargetIdentity) -> Bool { contains { if case .destroyOwnedTarget(let value, _, _) = $0 { return value == target }; return false } }
    var waitingTicket: AutomationSessionTicket? { for effect in self { if case .awaitCleanup(let ticket) = effect { return ticket } }; return nil }
    var cleanupTicket: AutomationSessionCleanupTicket? { for effect in self { if case .destroyOwnedTarget(_, _, let ticket) = effect { return ticket } }; return nil }
    func immediateCount(_ id: UUID) -> Int { filter { if case .reply(let reply) = $0 { return reply.requestID == id }; return false }.count }
    func completionCount(_ ticket: AutomationSessionTicket) -> Int { filter { if case .completion(let actual, _) = $0 { return actual == ticket }; return false }.count }
    var containsIndeterminatePossible: Bool { contains { let r: AutomationReply; switch $0 { case .reply(let value), .completion(_, let value): r = value; default: return false }; if case .failure(let error) = r.outcome { return error.code == .indeterminateResult && error.sideEffects == .possible && !error.retryable }; return false } }
    func containsReply(_ code: AutomationErrorCode) -> Bool { contains { let r: AutomationReply; switch $0 { case .reply(let value), .completion(_, let value): r = value; default: return false }; if case .failure(let e) = r.outcome { return e.code == code }; return false } }
    func containsReply(_ reply: AutomationReply) -> Bool { contains { switch $0 { case .reply(let r), .completion(_, let r): return r == reply; default: return false } } }
}
